            <span className="hidden max-w-[16ch] truncate text-[14px] text-white/70 sm:block">{app?.user.name}</span>
            <button type="button" aria-label="Sign out" title="Sign out" onClick={() => app?.auth.signOut()} className="grid h-11 w-11 place-items-center rounded-full text-white/75 transition-colors duration-150 hover:bg-white/10 hover:text-white"><LogOut className="h-5 w-5" /></button>
          </div>
        </div>
      </header>
      <nav aria-label="Main" className="fixed inset-x-0 bottom-0 z-40 grid grid-cols-2 border-t border-white/10 bg-[#0B0710]/95 pb-[env(safe-area-inset-bottom)] backdrop-blur md:hidden">
        {items.map((i) => {
          const on = active === i.k;
          return (
